import { defineSchema } from "../schemas/index.js";
import { snapshotBoundedJsonValue } from "../schemas/json-value.js";
export const MAX_DURABLE_RECORD_BYTES = 1024 * 1024;
export const MAX_DURABLE_RECORDS = 4096;
export const MAX_DURABLE_HOME_BYTES = 64 * 1024 * 1024;
export const getDurableRunIdentitySchema = defineSchema((v) => v.object({
    projectId: v.string().uuid(),
    canonicalRunId: v.string().uuid(),
    publicRunId: v.string().min(1).max(256),
    agentId: v.string().min(1).max(128).regex(/^[a-zA-Z0-9_-]+$/),
    threadId: v.string().uuid(),
    sourceHash: v.string().regex(/^[a-f0-9]{64}$/),
}).strict());
/** Copy data-only checkpoint/event payloads; credentials must never be supplied by callers. */
export function snapshotDurableValue(value) {
    const snapshot = snapshotBoundedJsonValue(value, MAX_DURABLE_RECORD_BYTES, MAX_DURABLE_RECORD_BYTES);
    if (!snapshot.success)
        throw new Error("Invalid durable run data");
    return snapshot.value;
}
